import subprocess

# Check the actual diff content of each commit
for commit in ["fab5eebd", "65a23ef2", "58b0febe"]:
    print(f"\n=== Commit {commit} ===")
    result = subprocess.run(["git", "show", "--no-stat", commit], capture_output=True, text=True)
    # Show just the diff part
    lines = result.stdout.split('\n')
    in_diff = False
    for line in lines:
        if line.startswith('diff --git'):
            in_diff = True
        if in_diff:
            print(line)
